<div class="card"><h1>Seller Reviews</h1><?php if(!empty($message)): ?><div class="alert"><?= e($message) ?></div><?php endif; ?><h2>Review Winning Buyers</h2><form method="post"><select name="buyer_id"><?php foreach($reviewableBuyers as $b): ?><option value="<?= $b['buyer_id'] ?>" data-listing="<?= $b['listing_id'] ?>"><?= e($b['title'].' - '.$b['buyer_name']) ?></option><?php endforeach; ?></select><input type="hidden" name="listing_id" id="reviewListingId" value="<?= e($reviewableBuyers[0]['listing_id'] ?? '') ?>"><select name="rating"><option value="5">5</option><option value="4">4</option><option value="3">3</option><option value="2">2</option><option value="1">1</option></select><textarea name="review_text" placeholder="Review the winning buyer"></textarea><button>Submit Buyer Review</button></form><script>document.querySelector('select[name="buyer_id"]')?.addEventListener('change',function(){document.getElementById('reviewListingId').value=this.options[this.selectedIndex].dataset.listing||'';});</script></div><div class="card"><h2>Reviews Received</h2><table><tr><th>Listing</th><th>Reviewer</th><th>Rating</th><th>Review</th><th>Response</th></tr><?php foreach($rows as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['reviewer_name']) ?></td><td><?= e($r['rating']) ?></td><td><?= e($r['review_text']) ?></td><td><form method="post"><input type="hidden" name="review_id" value="<?= $r['id'] ?>"><input name="response_text" value="<?= e($r['response_text']) ?>"><button>Respond</button></form></td></tr><?php endforeach; ?></table></div>
